-- PROPOSAL TESTS (local PG16) for proposals/0009_url_validation_PROPOSAL.sql. psql -v prop=0|1
\set ON_ERROR_STOP on
\i tests/helpers.sql
create or replace function pg_temp.try(stmt text) returns boolean language plpgsql as $$ begin execute stmt; return true; exception when others then return false; end $$;
insert into auth.users(id,email,email_confirmed_at) values ('00000000-0000-0000-0000-0000000000a1','a1@t.example',now());
insert into companies(id,slug,name,city,country,directory_status,claim_status,verification_status,data_review_status) values ('c0000000-0000-0000-0000-000000000001','c1','C1','Bhadohi','India','draft','approved','verified','pending');
\if :prop
\i proposals/0009_url_validation_PROPOSAL.sql
select pg_temp.ok('UV1 accepted: https, http, upper-case scheme, query, port, path', public.is_http_url('https://example.com') and public.is_http_url('http://a.b.in:8080/p?q=1&r=2#f') and public.is_http_url('HTTPS://EXAMPLE.COM/X'));
select pg_temp.ok('UV2 rejected schemes: javascript, data, file, ftp, vbscript, blob, mailto, tel, //proto-relative, scheme-less', not (public.is_http_url('javascript:alert(1)') or public.is_http_url('data:text/html,x') or public.is_http_url('file:///etc/passwd') or public.is_http_url('ftp://x.example') or public.is_http_url('vbscript:x') or public.is_http_url('blob:https://x.example/1') or public.is_http_url('mailto:a@b.co') or public.is_http_url('tel:+911') or public.is_http_url('//evil.example') or public.is_http_url('example.com')));
select pg_temp.ok('UV3 rejected: whitespace, control chars, angle brackets/quotes, userinfo, >500 chars, NULL, too short', not (public.is_http_url('https://x.example/a b') or public.is_http_url(E'https://x.example/\n') or public.is_http_url('https://x.example/<s>') or public.is_http_url('https://x.example/"onmouseover=') or public.is_http_url('https://user:pw@x.example') or public.is_http_url('https://x.example/'||repeat('a',500)) or public.is_http_url(null) or public.is_http_url('http://')));
select pg_temp.ok('UV4 website tolerance: scheme-less ok (example.com, www.x.in/path), other schemes still rejected', public.is_website_value('example.com') and public.is_website_value('www.x.in/path') and not public.is_website_value('javascript:alert(1)') and not public.is_website_value('data:x') and not public.is_website_value('ftp://x.example') and not public.is_website_value('x y.com'));
select pg_temp.ok('UV5 companies.website: safe values accepted, unsafe refused at the table', pg_temp.try($$update companies set website='example.com' where id='c0000000-0000-0000-0000-000000000001'$$) and not pg_temp.try($$update companies set website='javascript:alert(1)' where id='c0000000-0000-0000-0000-000000000001'$$));
select pg_temp.ok('UV6 company_sources.source_url: https and the internal direct-submission token accepted; javascript refused', pg_temp.try($$insert into company_sources(company_id,field_name,source_type,source_name,source_url,collected_at) values ('c0000000-0000-0000-0000-000000000001','name','official_website','x','https://x.example/a',now())$$) and pg_temp.try($$insert into company_sources(company_id,field_name,source_type,source_name,source_url,collected_at) values ('c0000000-0000-0000-0000-000000000001','name','direct_submission','x','direct-submission:00000000-0000-0000-0000-0000000000a1',now())$$) and not pg_temp.try($$insert into company_sources(company_id,field_name,source_type,source_name,source_url,collected_at) values ('c0000000-0000-0000-0000-000000000001','name','official_website','x','javascript:alert(1)',now())$$));
select pg_temp.ok('UV7 import batch/rows and image/contact URLs refuse unsafe schemes', not pg_temp.try($$insert into company_import_batches(source_type,source_name,source_url,terms_checked,operator_id,status) values ('official_website','x','data:text/html,x',true,'00000000-0000-0000-0000-0000000000a1','staged')$$) and pg_temp.try($$insert into company_import_batches(source_type,source_name,source_url,terms_checked,operator_id,status) values ('official_website','x','https://ok.example',true,'00000000-0000-0000-0000-0000000000a1','staged')$$) and not pg_temp.try($$insert into company_contacts(company_id,kind,value,source_type,source_name,source_url) values ('c0000000-0000-0000-0000-000000000001','email','a@b.co','official_website','x','file:///x')$$));
select pg_temp.ok('UV8 legacy rows are not scanned (NOT VALID): constraints exist unvalidated', (select count(*) from pg_constraint where conname in ('companies_website_safe','products_source_url_safe','company_sources_url_safe','company_contacts_url_safe','company_images_url_safe','product_images_url_safe','import_batches_url_safe','import_rows_website_safe') and not convalidated)=8);
\i proposals/0009_url_validation_DOWN.sql
select pg_temp.ok('UV9 DOWN removes constraints and functions', to_regprocedure('public.is_http_url(text)') is null and not exists(select 1 from pg_constraint where conname ~ '_(url|website)_safe$'));
\else
select pg_temp.ok('UC1 CONTROL (0007 only): javascript: is accepted in companies.website and company_sources.source_url', pg_temp.try($$update companies set website='javascript:alert(1)' where id='c0000000-0000-0000-0000-000000000001'$$) and pg_temp.try($$insert into company_sources(company_id,field_name,source_type,source_name,source_url,collected_at) values ('c0000000-0000-0000-0000-000000000001','name','official_website','x','javascript:alert(1)',now())$$));
select pg_temp.ok('UC2 CONTROL: public_company_sources (anon-readable) has no http(s) filter on source_url, so an unsafe value on a published company would be exposed', pg_get_viewdef('public.public_company_sources'::regclass) !~* 'https?');
\endif
\echo ALL URL-VALIDATION PROPOSAL TESTS COMPLETED (prop=:prop)
